def capital_words_spaces(s):
    if len(s) <= 1:
        return s

    words = []
    current_word = ""

    for i, char in enumerate(s):
        if char.isupper() and (i == 0 or not s[i-1].isalpha()):
            if current_word:
                words.append(current_word)
                current_word = ""

        current_word += char

    if current_word:
        words.append(current_word)

    return " ".join(words)

